import{_ as e,o as r,c as i,a2 as o}from"./chunks/framework.Kw_SGbqu.js";const p=JSON.parse('{"title":"备份与迁移","description":"","frontmatter":{},"headers":[],"relativePath":"guide/archive.md","filePath":"guide/archive.md"}'),t={name:"guide/archive.md"};function n(d,a,l,s,h,c){return r(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="备份与迁移" tabindex="-1">备份与迁移 <a class="header-anchor" href="#备份与迁移" aria-label="Permalink to &quot;备份与迁移&quot;">​</a></h1><p>Furina Archive 是跨端逻辑档案。它保存所选范围内、当前格式支持的档案和历史记录。游戏登录凭据与设备专属设置不随备份迁移；换机后可在新设备重新授权游戏账号。</p><h2 id="从-windows-迁移到-android-或反向迁移" tabindex="-1">从 Windows 迁移到 Android，或反向迁移 <a class="header-anchor" href="#从-windows-迁移到-android-或反向迁移" aria-label="Permalink to &quot;从 Windows 迁移到 Android，或反向迁移&quot;">​</a></h2><ol><li>打开源设备的备份与恢复功能，选择要导出的档案范围。</li><li>将生成的备份文件复制到目标设备可通过系统文件选择器访问的位置。</li><li>在目标设备选择该文件，等待校验，再查看目标映射、变更和冲突。</li><li>按预览确认恢复。恢复后重新打开应用，核对目标档案的账号、记录数和历史内容。</li></ol><h2 id="合并与范围替换" tabindex="-1">合并与范围替换 <a class="header-anchor" href="#合并与范围替换" aria-label="Permalink to &quot;合并与范围替换&quot;">​</a></h2><p><strong>合并</strong>适用于保留目标设备已有资料并补充历史；仔细核对已有档案及账号的映射。</p><p><strong>范围替换</strong>适用于明确希望用备份替换指定档案、账号或领域的情况。先确认影响范围及恢复点提示，再提交。范围替换使用专门的恢复机制，普通撤销历史无法代替恢复点。</p><h2 id="管理备份副本" tabindex="-1">管理备份副本 <a class="header-anchor" href="#管理备份副本" aria-label="Permalink to &quot;管理备份副本&quot;">​</a></h2><p>本地删除只处理应用能管理的本机数据。用户另存的文件和其他设备上的副本，应在对应位置管理。分享导出文件前请检查文件所含的个人游戏记录。</p>',9)])])}const u=e(t,[["render",n]]);export{p as __pageData,u as default};
